\documentclass[border=10pt]{standalone}
\usepackage{pgfplots}
\pgfplotsset{compat=1.17}
\begin{document}
\begin{tikzpicture}
\begin{axis}[
    xlabel={$y$}, ylabel={$z$}, zlabel={$x$},
    xmin=-2.2, xmax=2.2,
    ymin=-1.2, ymax=1.2,
    zmin=-0.2, zmax=4.5,
    view={-60}{20},
    samples=50,
    colormap/viridis,
    axis lines=middle,
    width=12cm,
    height=10cm,
    title={$x=y^2+4z^2$ (elliptic paraboloid)}
]
\addplot3[surf, shader=interp, opacity=0.7, domain=-2:2, y domain=-1:1] {y^2+4*z^2};

% Trace x=2 (ellipse)
\addplot3[red, thick, samples y=0, domain=0:360, variable=\t] 
    ({sqrt(2)*cos(\t)}, {sqrt(2)/2*sin(\t)}, {2});

% Trace z=0 (parabola x=y^2)
\addplot3[blue, thick, samples y=0, domain=-2:2, variable=\y] 
    ({\y}, {0}, {\y^2});

% Trace y=0 (parabola x=4z^2)
\addplot3[magenta, thick, samples y=0, domain=-1:1, variable=\z] 
    ({0}, {\z}, {4*\z^2});
\end{axis}
\end{tikzpicture}
\end{document}

